/* fcntl.h for a tree built against os9lib -- osk-freeware, 2026-08-24.   os9lib's own <fcntl.h> ends with       #define open   unix_open       #define creat  unix_creat   and NO library on this disk defines either -- not os9lib.l, not unix.l,   not blarslib.l (checked).  The library expects a companion this SDK does   not carry.  Its O_* values are wanted, though: they are OS-9's own access   modes, O_RDONLY is 1 rather than Unix's 0, and that is exactly why an   ordinary open() call works here at all.   So: take the header, drop the two renames.  Reached by absolute path   because -V=/h7/OS9LIB sits AHEAD of -V=/dd/DEFS/os9lib and a bare   #include <fcntl.h> would find this file again (os9lib's guard is #ifndef   _FCNTL_ around a #define _FCNTL, so it does not stop the recursion). */#include "/dd/DEFS/os9lib/fcntl.h"#undef open#undef creat